SELECT if(isNull(_num_value) OR isNull(_den_value) OR _den_value = 0, NULL, _num_value / _den_value) AS value FROM (SELECT value AS _num_value FROM (SELECT if((SELECT count() FROM (SELECT 1 FROM events WHERE properties['service.name'] = 'arena' AND timestamp <= now() - INTERVAL 86400 SECOND LIMIT 1)) > 0, count(), NULL) AS value FROM (SELECT NULL AS _metric_value FROM events WHERE properties['service.name'] = 'arena' AND timestamp >= now() - INTERVAL 86400 SECOND AND event = 'game_played') AS _source LIMIT 1) LIMIT 1) AS _num CROSS JOIN (SELECT value AS _den_value FROM (SELECT if((SELECT count() FROM (SELECT 1 FROM events WHERE properties['service.name'] = 'arena' AND timestamp <= now() - INTERVAL 2419200 SECOND LIMIT 1)) > 0, count(), NULL) AS value FROM (SELECT NULL AS _metric_value FROM events WHERE properties['service.name'] = 'arena' AND timestamp >= now() - INTERVAL 2419200 SECOND AND event = 'game_started') AS _source LIMIT 1) LIMIT 1) AS _den LIMIT 1
